import streamlit as stfrom PIL import Imagefrom google import genaist.set_page_config(    page_title="Kannada Homework Assistant",    page_icon="📚",    layout="centered")st.title("📚 Kannada Homework Assistant")st.markdown("Empowering parents to help with Kannada homework effortlessly.")# --- SECURELY LOAD FROM STREAMLIT SECRETS ---try:    api_key = st.secrets["GEMINI_API_KEY"]except Exception:    st.error("⚠️ Gemini API Key not found in Streamlit Secrets! Please configure it in your app settings.")    st.stop()# Initialize the GenAI clientclient = genai.Client(api_key=api_key)# Clean UI container for inputwith st.container():    upload_option = st.radio("Choose input method:", ["Upload Image File", "Take Photo with Phone Camera"], horizontal=True)    image = None    if upload_option == "Upload Image File":        uploaded_file = st.file_uploader("Upload Kannada textbook or question paper...", type=["jpg", "jpeg", "png", "webp"])        if uploaded_file is not None:            image = Image.open(uploaded_file)    else:        camera_file = st.camera_input("Snap a picture of the book page")        if camera_file is not None:            image = Image.open(camera_file)if image is not None:    st.image(image, caption="Uploaded Homework Page", use_container_width=True)        if st.button("✨ Process & Generate Guide", type="primary", use_container_width=True):        with st.spinner("Analyzing Kannada text, translating, and preparing study guide..."):            try:                prompt = """                You are an expert Kannada tutor helping a mother assist her 4th-grade son with homework.                Analyze this image of a Kannada textbook or question paper and provide the output in 4 clear, distinct sections using Markdown headers:                ### 1. Extracted Kannada Text                (The exact original Kannada text found in the image)                ### 2. Phonetic Transliteration (Manglish)                (How to read the Kannada text written out phonetically in English alphabets so an English speaker can easily pronounce and read it out loud)                ### 3. English Meaning & Explanation                (A clear, simple breakdown of what the text/question means, written so the mother can understand the concept and explain it to a 4th grader)                ### 4. Answers / Guidance (Bilingual)                (If there are questions to solve, provide the answers first in Kannada script so the mother can guide her son on how to write it, and right below it provide the English translation/guidance)                """                response = client.models.generate_content(                    model='gemini-3.8-flash',                    contents=[image, prompt]                )                st.success("Analysis Complete!")                st.markdown("---")                st.markdown(response.text)            except Exception as e:                st.error(f"An error occurred: {e}")